import{_ as o,C as r,o as a,c as i,ag as d,E as c}from"./chunks/framework.cyF4XceO.js";const b=JSON.parse('{"title":"バージョンモデル","description":"Takoform の互換性境界を定める 4 つの独立したバージョンの流れ。","frontmatter":{"title":"バージョンモデル","description":"Takoform の互換性境界を定める 4 つの独立したバージョンの流れ。"},"headers":[],"relativePath":"ja/docs/versions.md","filePath":"ja/docs/versions.md"}'),s={name:"ja/docs/versions.md"};function n(l,e,m,p,h,f){const t=r("StatusNote");return a(),i("div",null,[e[0]||(e[0]=d('<h1 id="バージョンモデル" tabindex="-1">バージョンモデル <a class="header-anchor" href="#バージョンモデル" aria-label="Permalink to &quot;バージョンモデル&quot;">​</a></h1><p>Takoform の現行モデルには、4 つのバージョンの流れだけがあります。前半の 2 つは domain の互換性、後半の 2 つは独立した software release です。</p><table tabindex="0"><thead><tr><th>流れ</th><th>現在の形</th><th>所有範囲と意味</th></tr></thead><tbody><tr><td>Host API</td><td><code>forms.takoform.com/v1</code></td><td>discovery と operation の literal lane。互換性のある変更はこの lane に収まり、<code>/v1.1</code> route はありません。</td></tr><tr><td>Form</td><td>各 Form の <code>definitionVersion</code></td><td>正確な service shape と lifecycle contract。family は versionless で、各 Form が自身の定義 version を持ちます。</td></tr><tr><td>Core ライブラリ</td><td><code>v1.1.0</code></td><td>独立して release される Core module / library。SemVer は Host API や Provider の version を決めません。</td></tr><tr><td>Provider</td><td><code>3.0.0</code></td><td>この repository の Registry 公開済み typed mapping。SemVer は Form や host capability を公開しません。</td></tr></tbody></table><h2 id="バージョンの流れではないもの" tabindex="-1">バージョンの流れではないもの <a class="header-anchor" href="#バージョンの流れではないもの" aria-label="Permalink to &quot;バージョンの流れではないもの&quot;">​</a></h2><p>Specification 1.1 receipt は normative evidence の一回限りの履歴 snapshot です。 現行の release train ではなく、Host API lane も作りません。撤回された Specification 1.0 identity は履歴資料としてだけ残ります。</p><p>Form Package の envelope、schema の <code>$id</code>、content digest、record format、family label、Provider descriptor は artifact または公開状態の識別子です。5 つ目の 流れを追加するものではありません。</p><h2 id="form-identity-の読み方" tabindex="-1">Form identity の読み方 <a class="header-anchor" href="#form-identity-の読み方" aria-label="Permalink to &quot;Form identity の読み方&quot;">​</a></h2><p>host が公開する Form は package や Provider の label ではなく、完全な FormRef として読みます。<code>formId</code> が service shape を選び、<code>definitionVersion</code> がその Form の contract revision を選びます。受け取った bytes は content digest で 固定し、family label は関連 Form の discovery 用に使います（family 自体は versionless です）。</p><p>Provider は対応する FormRef の typed surface を compile します。未知の Form 用 generic carrier はなく、Provider release が Form definition を暗黙に更新する こともありません。</p><h2 id="provider-release-の履歴" tabindex="-1">Provider release の履歴 <a class="header-anchor" href="#provider-release-の履歴" aria-label="Permalink to &quot;Provider release の履歴&quot;">​</a></h2><p>次の値は不変の配布記録であり、現行の追加 stream ではありません。</p><table tabindex="0"><thead><tr><th>Provider release</th><th>履歴上の役割</th></tr></thead><tbody><tr><td><code>3.0.0</code></td><td>現在の Experimental Form 31 個を mapping する Registry 公開済み release。</td></tr><tr><td><code>2.1.1</code></td><td>過去の Host API v1beta1 lane 用に保持する compatibility client。</td></tr><tr><td><code>2.0.0</code></td><td>撤回された v1alpha2 epoch 用に保持する client。</td></tr><tr><td><code>1.0.3</code></td><td>撤回された v1alpha1 epoch 用に保持する Legacy client。</td></tr></tbody></table><p>撤回された epoch に依存する state は、対応する Provider release を exact pin の まま維持します。移行する場合は <a href="/release/migrations/v2-to-v3.html">v2 から v3 の移行境界</a> を参照してください。自動 migration はありません。</p><h2 id="実際の確認順" tabindex="-1">実際の確認順 <a class="header-anchor" href="#実際の確認順" aria-label="Permalink to &quot;実際の確認順&quot;">​</a></h2><ol><li>host の literal Host Support Profile と <code>forms.takoform.com/v1</code> endpoint を確認します。</li><li>field を書く前に Form の <code>formId</code> と <code>definitionVersion</code> を確認します。</li><li>host integration が使う Core ライブラリの SemVer を固定します。</li><li>Terraform / OpenTofu の Provider SemVer を固定し、plan を確認します。</li></ol><p><a href="/ja/docs/reference.html">リファレンスの入口</a>から現行 resource を、<a href="/ja/docs/history.html">履歴</a> から Specification evidence と旧 URL の扱いを確認できます。</p>',16)),c(t)])}const y=o(s,[["render",n]]);export{b as __pageData,y as default};
